// --- 1. Acceso a los datos de entrada ---
// Se eliminó la entrada 'taggingData', ya que no es necesaria.
const campaignData = $('campañas-action').first().json;
const clientData = $('data-entry').first().json;


// --- 2. Extracción de Datos ---
const { campañas: todasLasCampanas, action } = campaignData;
const { nombre: clienteNombre, empresa: clienteEmpresa, "ID-cuenta-publicitaria": idCuentaPublicitaria } = clientData;


// --- 3. Construcción del Texto de Análisis ---
let estadoGeneral = "Reporte Existente";
let textoFinal = null;

// 3.1. Se define un título de análisis basado en el 'action'.
let tituloAnalisis;
switch (action) {
    case 'remarketing_menos_3': // Asumo que el valor podría ser _3 como en el código de Python.
    case 'remarketing_menos_2':
        tituloAnalisis = "ALERTA: Ausencia de Remarketing y <3 Campañas Activas";
        break;
    case 'remarketing':
        tituloAnalisis = "ALERTA: Ausencia de Campaña de Remarketing";
        break;
    case 'menos_3': // Asumo que el valor podría ser _3 como en el código de Python.
    case 'menos_2':
        tituloAnalisis = "AVISO: Menos de 3 Campañas Activas";
        break;
    default:
        tituloAnalisis = "INFORME GENERAL DE CAMPAÑAS";
        break;
}

// 3.2. Se prepara la información del cliente.
const infoCliente = `*Cliente:* ${clienteNombre}\n*Empresa:* ${clienteEmpresa}\n*ID Cuenta Publicitaria:* ${idCuentaPublicitaria}`;

// 3.3. Se prepara la lista de campañas activas.
let listaCampañasTexto = "\n*Campañas Activas:*";
if (todasLasCampanas && todasLasCampanas.length > 0) {
    todasLasCampanas.forEach(campana => {
        listaCampañasTexto += `\n• ${campana.name}`;
    });
} else {
    listaCampañasTexto += "\n_No hay campañas activas para mostrar._";
}

// 3.4. Se ensambla el texto final.
textoFinal = `${tituloAnalisis}\n\n${infoCliente}\n${listaCampañasTexto}`;


// --- 4. Objeto de Salida ---
// Se retorna un objeto estandarizado para ser usado por el siguiente nodo.
return [{
    json: {
        estado_general: estadoGeneral,
        texto_final: textoFinal
    }
}];

const data = $input.first().json;
let action;

const existe = data['existe-remarketing'];
const menos = data['menos-de-2-campañas'];

if (!existe && menos) {
  action = 'remarketing_menos_2';
} else if (!existe && !menos) {
  action = 'remarketing';
} else if (existe && menos) {
  action = 'menos_2';
} else {
  action = 'no-action';
